description:
Implement a hook that returns a sorted copy of an array using `useMemo`. The original array must not be mutated, and the sort is only recomputed when `items` or `compareFn` changes.

**Example:**
```tsx
const sorted = useMemoSort([3, 1, 2], (a, b) => a - b);
// sorted === [1, 2, 3]
```

starter_code:
import { useMemo } from 'react';

export function useMemoSort<T>(items: T[], compareFn: (a: T, b: T) => number): T[] {
  // your code here
}

test_suite:
test('sorts numbers ascending', () => {
  const { result } = renderHook(() => useMemoSort([3, 1, 4, 1, 5], (a, b) => a - b));
  expect(result.current).toEqual([1, 1, 3, 4, 5]);
});

test('sorts strings alphabetically', () => {
  const { result } = renderHook(() =>
    useMemoSort(['banana', 'apple', 'cherry'], (a, b) => a.localeCompare(b))
  );
  expect(result.current).toEqual(['apple', 'banana', 'cherry']);
});

test('sorts descending', () => {
  const { result } = renderHook(() => useMemoSort([1, 3, 2], (a, b) => b - a));
  expect(result.current).toEqual([3, 2, 1]);
});

test('does not mutate original array', () => {
  const items = [3, 1, 2];
  renderHook(() => useMemoSort(items, (a, b) => a - b));
  expect(items).toEqual([3, 1, 2]);
});

// __hidden__
test('returns empty array for empty input', () => {
  const { result } = renderHook(() => useMemoSort([], (a, b) => (a as number) - (b as number)));
  expect(result.current).toEqual([]);
});

solution:
import { useMemo } from 'react';

export function useMemoSort<T>(items: T[], compareFn: (a: T, b: T) => number): T[] {
  return useMemo(() => [...items].sort(compareFn), [items, compareFn]);
}
